#import "KARPACrossReference.h"
NSDictionary *KARPABuildCrossReference(NSDictionary *r){NSMutableDictionary *selectors=[NSMutableDictionary dictionary];NSMutableArray *relations=[NSMutableArray array];for(NSDictionary *c in r[@"classes"]?:@[]){NSString *cn=c[@"name"]?:@"";if(c[@"superclass"]&&c[@"superclass"]!=[NSNull null])[relations addObject:@{ @"fromClass":cn,@"toClass":c[@"superclass"],@"kind":@"superclass",@"evidence":@"RUNTIME_CONFIRMED"}];for(id p in c[@"protocols"]?:@[]){NSString *pn=[p isKindOfClass:NSString.class]?p:[(NSDictionary *)p objectForKey:@"name"];if(pn)[relations addObject:@{ @"fromClass":cn,@"toProtocol":pn,@"kind":@"adopts-protocol",@"evidence":@"RUNTIME_CONFIRMED"}];}for(NSDictionary *m in [c[@"methods"]?:@[] arrayByAddingObjectsFromArray:c[@"classMethods"]?:@[]]){NSString *s=m[@"selector"]?:@"";NSMutableArray *list=selectors[s]?:[NSMutableArray array];[list addObject:@{ @"class":cn,@"kind":m[@"kind"]?:@"",@"typeEncoding":m[@"typeEncoding"]?:@"",@"imp":m[@"imp"]?:@"",@"image":m[@"image"]?:@"",@"direct":m[@"direct"]?:@NO}];selectors[s]=list;}}return @{ @"selectors":selectors,@"relations":relations,@"evidence":@"RUNTIME_CONFIRMED"};}
